mapper.select:
SELECT f.follower_id FROM creator_follow f
INNER JOIN identity_user u ON u.id = f.follower_id AND u.status = 'ACTIVE'
INNER JOIN creator_profile p ON p.user_id = f.creator_id AND p.status = 'ACTIVE'
WHERE f.creator_id = #{creatorId} AND f.follower_id > #{afterId}
ORDER BY f.follower_id LIMIT #{size}
